// KS-864 (QA gate on PR #1009, R-1 row Q-nullish): #1007 set each portal URL in routes/system-status.ts to
// process.env.<X>_PORTAL_URL || '<compose default>'. No cell set a portal var to the EMPTY string, so the
// tamper || -> ?? (an empty var served as the url) reddened 0 cells. An empty var must fall back to the
// compose default. The module reads the vars at load, so the env is set before a fresh import.
import { describe, it, expect, vi, beforeAll, afterAll } from 'vitest';
import http from 'node:http';
import express from 'express';
vi.mock('../services/redis', () => ({ getRedisHealth: vi.fn(async () => ({ status: 'healthy' })) }));
const PORTALS = ['ISSUER_PORTAL_URL', 'VERIFIER_PORTAL_URL', 'ADMIN_PORTAL_URL'];
const savedEnv = { ...process.env };
let server: ReturnType<ReturnType<typeof express>['listen']>;
let urls: Record<string, string | undefined> = {};
beforeAll(async () => {
  vi.resetModules();
  vi.stubGlobal('fetch', vi.fn(async () => { throw new Error('offline in test'); }));
  process.env.NODE_ENV = 'dev';
  for (const v of PORTALS) process.env[v] = '';
  process.env.BILLING_SERVICE_URL = '';
  const router = (await import('../routes/system-status')).default;
  const app = express();
  app.use('/api/system', router);
  const port = await new Promise<number>((r) => { server = app.listen(0, '127.0.0.1', () => r((server.address() as any).port)); });
  const body = await new Promise<any>((resolve, reject) => {
    http.get({ hostname: '127.0.0.1', port, path: '/api/system/status' }, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } });
    }).on('error', reject);
  });
  const services = Object.values(body.services).flat() as Array<{ name?: string; url?: string }>;
  urls = Object.fromEntries(services.map((s) => [s.name, s.url]));
}, 10_000);
afterAll(async () => {
  await new Promise<void>((r) => server.close(() => r()));
  for (const k of Object.keys(process.env)) if (!(k in savedEnv)) delete process.env[k];
  Object.assign(process.env, savedEnv);
  vi.unstubAllGlobals();
});
describe('KS-864 an EMPTY portal env var falls back to its compose default (NODE_ENV=dev)', () => {
  it('KS-864 R-1: issuer-portal reports http://issuer-frontend:80 when ISSUER_PORTAL_URL is empty', () => {
    expect(urls['issuer-portal']).toBe('http://issuer-frontend:80');
  });
  it('KS-864 R-1: verifier-portal reports http://verifier-frontend:80 when VERIFIER_PORTAL_URL is empty', () => {
    expect(urls['verifier-portal']).toBe('http://verifier-frontend:80');
  });
  it('KS-864 R-1: admin-portal reports http://admin-frontend:80 when ADMIN_PORTAL_URL is empty', () => {
    expect(urls['admin-portal']).toBe('http://admin-frontend:80');
  });
  it('control: billing reports its localhost default when BILLING_SERVICE_URL is empty', () => {
    expect(urls['billing']).toBe('http://localhost:4019');
  });
  it('control: the three portal rows are served', () => {
    expect(['issuer-portal', 'verifier-portal', 'admin-portal'].map((n) => n in urls)).toEqual([true, true, true]);
  });
});
